-- UUIDs are generated by JPA; production and tests both use PostgreSQL.
CREATE TABLE uls (
    id UUID PRIMARY KEY,
    name VARCHAR(255) NOT NULL CHECK (btrim(name) <> '')
);

CREATE TABLE healthcare_units (
    id UUID PRIMARY KEY,
    name VARCHAR(255) NOT NULL CHECK (btrim(name) <> ''),
    uls_id UUID NOT NULL REFERENCES uls(id)
);

CREATE TABLE buildings (
    id UUID PRIMARY KEY,
    name VARCHAR(255) NOT NULL CHECK (btrim(name) <> ''),
    unit_id UUID NOT NULL REFERENCES healthcare_units(id)
);

CREATE TABLE floors (
    id UUID PRIMARY KEY,
    level_name VARCHAR(255) NOT NULL CHECK (btrim(level_name) <> ''),
    building_id UUID NOT NULL REFERENCES buildings(id)
);

-- Nova tabela adicionada na posição correta da hierarquia (Floor -> Service)
CREATE TABLE clinical_services (
    id UUID PRIMARY KEY,
    code VARCHAR(255) NOT NULL CHECK (btrim(code) <> ''),
    name VARCHAR(255) NOT NULL CHECK (btrim(name) <> ''),
    floor_id UUID NOT NULL REFERENCES floors(id),
    UNIQUE (floor_id, code)
);

-- Wings passa a ter service_id em vez de floor_id
CREATE TABLE wings (
    id UUID PRIMARY KEY,
    name VARCHAR(255) NOT NULL CHECK (btrim(name) <> ''),
    service_id UUID NOT NULL REFERENCES clinical_services(id)
);

CREATE TABLE wards (
    id UUID PRIMARY KEY,
    code VARCHAR(255) NOT NULL UNIQUE CHECK (btrim(code) <> ''),
    name VARCHAR(255) NOT NULL CHECK (btrim(name) <> ''),
    wing_id UUID NOT NULL REFERENCES wings(id)
);

CREATE TABLE rooms (
    id UUID PRIMARY KEY,
    code VARCHAR(255) NOT NULL CHECK (btrim(code) <> ''),
    ward_id UUID NOT NULL REFERENCES wards(id),
    UNIQUE (ward_id, code)
);

CREATE TABLE beds (
    id UUID PRIMARY KEY,
    code VARCHAR(255) NOT NULL CHECK (btrim(code) <> ''),
    room_id UUID NOT NULL REFERENCES rooms(id),
    status VARCHAR(255) NOT NULL CHECK (status IN ('AVAILABLE', 'OCCUPIED')),
    version BIGINT NOT NULL DEFAULT 0,
    UNIQUE (room_id, code)
);

CREATE TABLE patients (
    id UUID PRIMARY KEY,
    sns_number VARCHAR(255) NOT NULL UNIQUE CHECK (btrim(sns_number) <> ''),
    hospital_number VARCHAR(255),
    full_name VARCHAR(255) NOT NULL CHECK (btrim(full_name) <> ''),
    birth_date DATE,
    gender VARCHAR(255)
);

CREATE TABLE encounters (
    id UUID PRIMARY KEY,
    visit_number VARCHAR(255) NOT NULL UNIQUE CHECK (btrim(visit_number) <> ''),
    patient_id UUID NOT NULL REFERENCES patients(id),
    status VARCHAR(255) NOT NULL CHECK (status IN ('IN_PROGRESS', 'FINISHED')),
    start_period TIMESTAMP(6) WITH TIME ZONE,
    end_period TIMESTAMP(6) WITH TIME ZONE,
    CHECK (end_period IS NULL OR start_period IS NULL OR end_period >= start_period),
    CHECK (status <> 'IN_PROGRESS' OR end_period IS NULL)
);

CREATE TABLE location_allocations (
    id UUID PRIMARY KEY,
    encounter_id UUID NOT NULL REFERENCES encounters(id),
    bed_id UUID NOT NULL REFERENCES beds(id),
    assigned_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    discharged_at TIMESTAMP(6) WITH TIME ZONE,
    CHECK (discharged_at IS NULL OR discharged_at >= assigned_at)
);

-- Closed allocations remain in the history. Only open allocations are exclusive.
CREATE UNIQUE INDEX uq_open_allocation_bed ON location_allocations(bed_id)
    WHERE discharged_at IS NULL;
CREATE UNIQUE INDEX uq_open_allocation_encounter ON location_allocations(encounter_id)
    WHERE discharged_at IS NULL;

CREATE TABLE conditions (
    code VARCHAR(32) PRIMARY KEY, 
    system  VARCHAR(16),
    name    TEXT NOT NULL
);

CREATE INDEX ix_units_uls ON healthcare_units(uls_id);
CREATE INDEX ix_buildings_unit ON buildings(unit_id);
CREATE INDEX ix_floors_building ON floors(building_id);
CREATE INDEX ix_clinical_services_floor ON clinical_services(floor_id);
CREATE INDEX ix_wings_service ON wings(service_id);
CREATE INDEX ix_wards_wing ON wards(wing_id);
CREATE INDEX ix_encounters_patient ON encounters(patient_id);
CREATE INDEX ix_encounters_status ON encounters(status);
CREATE INDEX ix_allocations_encounter ON location_allocations(encounter_id);
CREATE INDEX ix_allocations_bed ON location_allocations(bed_id);